import{_ as o,a0 as r,w as d,s as f,ao as i,I as u,x as e,a1 as a,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何在 Ubuntu 上比較 PDF 文件 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 上比較 PDF 文件 | LCTT (201508) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 上比較 PDF 文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 上比較 PDF 文件 | LCTT (201508) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201508/20150730 Compare PDF Files on Ubuntu","title":"如何在 Ubuntu 上比較 PDF 文件","tag":"201508","desc":""},"relativePath":"201508/20150730 Compare PDF Files on Ubuntu.md","filePath":"[post].md"}'),l={name:"201508/20150730 Compare PDF Files on Ubuntu.md"};function s(m,t,b,P,h,D){const p=r("Link");return d(),f("div",null,[t[13]||(t[13]=i(`<h1 id="如何在-ubuntu-上比較-pdf-文件" tabindex="-1">如何在 Ubuntu 上比較 PDF 文件 <a class="header-anchor" href="#如何在-ubuntu-上比較-pdf-文件" aria-label="Permalink to “如何在 Ubuntu 上比較 PDF 文件”">​</a></h1><p>如果你想要對PDF文件進行比較，你可以使用下面工具之一。</p><h3 id="comparepdf" tabindex="-1">Comparepdf <a class="header-anchor" href="#comparepdf" aria-label="Permalink to “Comparepdf”">​</a></h3><p>comparepdf是一個命令列應用，用於將兩個PDF文件進行對比。默認對比模式是文本模式，該模式會對各對相關頁面進行文字對比。只要一檢測到差異，該程序就會終止，並顯示一條信息（除非設置了-v0）和一個指示性的返回碼。</p><p>用於文本模式對比的選項有 -ct 或 --compare=text（默認），用於視覺對比（這對圖標或其它圖像發生改變時很有用）的選項有 -ca 或 --compare=appearance。而 -v=1 或 --verbose=1 選項則用於報告差異（或者對匹配文件不作任何回應）；使用 -v=0 選項取消報告，或者 -v=2 來同時報告不同的和匹配的文件。</p><h4 id="安裝comparepdf到ubuntu" tabindex="-1">安裝comparepdf到Ubuntu <a class="header-anchor" href="#安裝comparepdf到ubuntu" aria-label="Permalink to “安裝comparepdf到Ubuntu”">​</a></h4><p>打開終端，然後運行以下命令</p><pre><code>sudo apt-get install comparepdf
</code></pre><p><strong>Comparepdf 語法</strong></p><pre><code>comparepdf [OPTIONS] file1.pdf file2.pdf
</code></pre><p>###Diffpdf###</p><p>DiffPDF是一個圖形化應用程序，用於對兩個PDF文件進行對比。默認情況下，它只會對比兩個相關頁面的文字，但是也支持對圖形化頁面進行對比（例如，如果圖表被修改過，或者段落被重新格式化過）。它也可以對特定的頁面或者頁面範圍進行對比。例如，如果同一個PDF文件有兩個版本，其中一個有頁面1-12，而另一個則有頁面1-13，因為這裏添加了一個額外的頁面4，它們可以通過指定兩個頁面範圍來進行對比，第一個是1-12，而1-3,5-13則可以作為第二個頁面範圍。這將使得DiffPDF成對地對比這些頁面（1,1），（2,2），（3,3），（4,5），（5,6），以此類推，直到（12,13）。</p><h4 id="安裝-diffpdf-到-ubuntu" tabindex="-1">安裝 diffpdf 到 ubuntu <a class="header-anchor" href="#安裝-diffpdf-到-ubuntu" aria-label="Permalink to “安裝 diffpdf 到 ubuntu”">​</a></h4><p>打開終端，然後運行以下命令</p><pre><code>sudo apt-get install diffpdf
</code></pre><h4 id="截圖" tabindex="-1">截圖 <a class="header-anchor" href="#截圖" aria-label="Permalink to “截圖”">​</a></h4><p><img src="http://www.ubuntugeek.com/wp-content/uploads/2015/07/14.png" alt=""></p><p><img src="http://www.ubuntugeek.com/wp-content/uploads/2015/07/23.png" alt=""></p><hr>`,19)),u("p",null,[t[1]||(t[1]=e("via: ",-1)),a(p,{href:"http://www.ubuntugeek.com/compare-pdf-files-on-ubuntu.html"},{default:n(()=>[...t[0]||(t[0]=[e("http://www.ubuntugeek.com/compare-pdf-files-on-ubuntu.html",-1)])]),_:1})]),u("p",null,[t[5]||(t[5]=e("作者：",-1)),a(p,{href:"http://www.ubuntugeek.com/author/ubuntufix"},{default:n(()=>[...t[2]||(t[2]=[e("ruchi",-1)])]),_:1}),t[6]||(t[6]=e(" 譯者：",-1)),a(p,{href:"https://github.com/GOLinux"},{default:n(()=>[...t[3]||(t[3]=[e("GOLinux",-1)])]),_:1}),t[7]||(t[7]=e(" 校對：",-1)),a(p,{href:"https://github.com/wxy"},{default:n(()=>[...t[4]||(t[4]=[e("wxy",-1)])]),_:1})]),u("p",null,[t[10]||(t[10]=e("本文由 ",-1)),a(p,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[8]||(t[8]=[e("LCTT",-1)])]),_:1}),t[11]||(t[11]=e(" 原創翻譯，",-1)),a(p,{href:"https://linux.cn/"},{default:n(()=>[...t[9]||(t[9]=[e("Linux中國",-1)])]),_:1}),t[12]||(t[12]=e(" 榮譽推出",-1))])])}const g=o(l,[["render",s]]);export{x as __pageData,g as default};
